package financeos.vk;
import financeos.core.*;import financeos.data.*;import java.time.*;import java.util.*;import java.nio.file.*;import java.io.*;import javax.imageio.ImageIO;
public final class Release18Test {
 static long id;static final Clock CLOCK=Clock.fixed(Instant.parse("2026-11-27T10:00:00Z"),ZoneId.of("Europe/Moscow"));
 static BotReply send(LocalBotEngine e,String text){var r=e.handle(new VkEvent("message_new",99,42,42,"r18-"+(++id),text)).orElseThrow();new VkKeyboardFactory().keyboard(r.buttons()==null?MenuCatalog.buttons(r.screen()):r.buttons());return r;}
 static void check(boolean v,String s){if(!v)throw new AssertionError(s);}
 static void has(BotReply r,String s){check(r.text().contains(s),"Missing "+s+": "+r.text());}
 static LocalBotEngine reload(LocalBotEngine e,LegacyUserData data,Path path)throws Exception{var f=new LocalStateFile(path,42,data);f.save(e.exportState());var n=new LocalBotEngine(42,data,CLOCK);n.restoreState(f.load().orElseThrow());return n;}
 static void section(LocalBotEngine e,String name){send(e,"/sections");send(e,"/section_pick");send(e,name);}
 static void category(LocalBotEngine e,String section,String category){section(e,section);send(e,"/section_categories");send(e,category);}
 public static void main(String[] args)throws Exception{
  var month=YearMonth.of(2026,11);var data=new LegacyUserData(Money.of("10000"),OffsetDateTime.parse("2026-11-01T00:00:00+03:00"),List.of(new LegacyUserData.TimedEntry(OffsetDateTime.parse("2026-11-02T00:00:00+03:00"),new LedgerEntry("old",LocalDate.of(2026,11,2),EntryKind.EXPENSE,Money.of("100"),"Еда","тест",false))),List.of(new BudgetPlan(month,"Еда",Money.of("1000")),new BudgetPlan(month,"Бензин",Money.of("2000")),new BudgetPlan(month.plusMonths(1),"Еда",Money.of("3000"))));
  var e=new LocalBotEngine(42,data,CLOCK);var cfg=LocalBotEngine.class.getDeclaredField("categorySections");cfg.setAccessible(true);cfg.set(e,new CategorySections(List.of("Питание","Машина"),Map.of("Еда","Питание","Бензин","Машина"),Map.of(),Set.of()));
  Path dir=Files.createTempDirectory("r18-"),file=dir.resolve("state.json");try{
   send(e,"/delete_plan");send(e,"2026-11");send(e,"Питание");has(send(e,"Еда"),"Категорий · 1");check(e.exportState().planEdits().isEmpty(),"Preview deleted plan");e=reload(e,data,file);has(send(e,"/section_confirm"),"План удалён");check(e.exportState().planEdits().getLast().deleted(),"No deletion marker");e=reload(e,data,file);var effective=new PlanEditService().apply(data,e.exportState().planEdits());check(effective.plans().size()==2&&effective.transactions().equals(data.transactions()),"Plan delete lost history/other month");send(e,"/undo");check(e.exportState().planEdits().isEmpty(),"Deletion undo");
   send(e,"/delete_plan");send(e,"2026-11");send(e,"Машина");has(send(e,"/delete_plan_section_all"),"Категорий · 1");send(e,"/section_confirm");send(e,"/add_plan");send(e,"500, Бензин");var recreated=new PlanEditService().apply(new LegacyUserData(data.startingBalance(),data.snapshotTime(),data.transactions(),java.util.stream.Stream.concat(data.plans().stream(),e.exportState().plans().stream()).toList()),e.exportState().planEdits());check(recreated.plans().stream().filter(p->p.month().equals(month)&&p.category().equals("Бензин")).map(BudgetPlan::amount).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add).compareTo(Money.of("500"))==0,"Deleted plan restored old amount during recreation");send(e,"/undo");send(e,"/undo");
   send(e,"/salary_rule");send(e,"50000; 27; зарплата");send(e,"/regular_confirm");has(send(e,"rule-1@2026-11-27"),"Проверьте");check(e.exportState().entries().isEmpty(),"Preview recorded salary");send(e,"/regular_amount");has(send(e,"-1"),"положительную");send(e,"40000");e=reload(e,data,file);has(send(e,"/regular_accept"),"40000");check(e.exportState().entries().getLast().entry().amount().compareTo(Money.of("40000"))==0,"Wrong occurrence amount");check(e.exportState().recurring().rules().getFirst().amount().compareTo(Money.of("50000"))==0,"Future rule changed");send(e,"/regular_accept");check(e.exportState().entries().size()==1,"Double acceptance");send(e,"/undo");
   section(e,"Машина");has(send(e,"/section_delete"),"получатель");send(e,"Питание");e=reload(e,data,file);send(e,"/section_confirm");check(e.exportState().categorySections().section("Бензин").equals("Питание"),"Section relocation");check(!e.exportState().categorySections().names().contains("Машина"),"Source remains");send(e,"/undo");
   category(e,"Питание","Еда");send(e,"/category_merge");has(send(e,"Бензин"),"сложатся");e=reload(e,data,file);send(e,"/section_confirm");var merged=e.exportState().categorySections().apply(data);check(merged.transactions().getFirst().entry().category().equals("Бензин"),"History merge");check(new BudgetService().breakdown(month,merged.plans(),List.of()).getFirst().planned().compareTo(Money.of("3000"))==0,"Month plans not summed");send(e,"/undo");
   send(e,"/section_new");var suggestion=send(e,"Питане");has(suggestion,"уже существует");check(!e.exportState().categorySections().names().contains("Питане"),"Suggestion mutated structure");var suggested=suggestion.buttons().stream().filter(b->b.command().startsWith("/section_suggest/")).findFirst().orElseThrow();has(send(e,suggested.command()),"Питание");
   has(send(e,"/appearance"),"вручную");byte[] wallpaper=send(e,"/appearance_wallpaper").imagePng();check(wallpaper[0]==(byte)0x89&&wallpaper[1]=='P'&&wallpaper[2]=='N'&&wallpaper[3]=='G',"VK upload requires PNG");check(ImageIO.read(new ByteArrayInputStream(wallpaper)).getHeight()>1000,"Wallpaper asset");check(ImageIO.read(new ByteArrayInputStream(send(e,"/appearance_bubbles").imagePng()))!=null,"Bubble asset");check(send(e,"/back").screen()==Screen.APPEARANCE,"Appearance Back lost parent");
   var report=send(e,"/report_chart");check(report.images().size()>=3,"Complete styled report missing");var png=ImageIO.read(new ByteArrayInputStream(report.images().getFirst()));check(png.getRGB(png.getWidth()-1,0)!=png.getRGB(0,png.getHeight()-1),"No upper-right gradient");
   send(e,"/plan_copy_next");send(e,"/plan_copy_confirm");send(e,"/delete_plan");send(e,"2026-12");send(e,"Машина");send(e,"Бензин");send(e,"/delete_plan_confirm");send(e,"/plan_copy_next");send(e,"/plan_copy_confirm");var copied=new PlanEditService().apply(new LegacyUserData(data.startingBalance(),data.snapshotTime(),data.transactions(),java.util.stream.Stream.concat(data.plans().stream(),e.exportState().plans().stream()).toList()),e.exportState().planEdits());check(copied.plans().stream().filter(p->p.month().equals(month.plusMonths(1))&&p.category().equals("Бензин")).map(BudgetPlan::amount).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add).compareTo(Money.of("2000"))==0,"Deleted copied plan disappeared or doubled");
   check(data.plans().size()==3&&data.transactions().getFirst().entry().category().equals("Еда"),"Original fixture mutated");
  }finally{Files.deleteIfExists(file);Files.deleteIfExists(dir);}
  System.out.println("Release18: original plan deletion, whole section, restart/undo, recurring edit, merge, relocation, assets, invariants passed.");
 }
}
